import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;
import com.crowdin.client.stringtranslations.model.LanguageTranslations;
import com.crowdin.client.sourcefiles.model.FileInfo;

public class JacksonJsonTransformerTest {

    @Test
    public void parseValidJsonTest() {
		JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String validJson = "{\"translationId\":1,\"languageId\":\"ja\",\"text\":\"こんにちは\"}";
        LanguageTranslations translations = transformer.parse(validJson, LanguageTranslations.class);

        assertNotNull(translations);
        assertTrue(translations.getLanguageId().equals("ja"));
    }

    @Test(expected = CrowdinApiException.class)
    public void parseInvalidJsonTest() {
		JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String invalidJson = "{\"translationID\":invalid,\"languageId\":\"ja\",\"text\":\"こんにちは\"}";
        transformer.parse(invalidJson, LanguageTranslations.class);
    }

    @Test
    public void convertValidObjectTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        FileInfo fileInfo = new FileInfo();
        fileInfo.setName("test.txt");
        fileInfo.setSize(100L);

        String jsonString = transformer.convert(fileInfo);

        assertNotNull(jsonString);
        assertTrue(jsonString.contains("\"name\":\"test.txt"));
        assertTrue(jsonString.contains("\"size\":100"));
    }

    @Test(expected = CrowdinApiException.class)
    public void convertInvalidObjectTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        LanguageTranslations languageTranslations = new LanguageTranslations(); //Required fields are not set

        String jsonString = transformer.convert(languageTranslations);
    }
}
